#!/usr/bin/env python3
"""Build a deterministic, offline-capable Delta AutoExecute bundle."""
from pathlib import Path
import argparse

ROOT = Path(__file__).resolve().parents[1]
MODULES = ("Core", "KeyboardRoute", "Controls", "GridSensor", "CameraGate", "Runtime")
OUTPUT = ROOT / "PC_Movement_Rebuild_AUTOEXECUTE.lua"

def bundle():
    sections = [
        "-- PC Movement Rebuild / Delta iOS AutoExecute\n"
        "-- Generated by tools/build_rebuild.py; edit rebuild/*.lua instead.\n"
        "-- One native keyboard owner. No runtime downloads or physics writes.\n"
        "-- Physics and map/emote signals still require on-device validation.\n"
    ]
    for name in MODULES:
        source = (ROOT / "rebuild" / f"{name}.lua").read_text()
        sections.append(f"local function build{name}()\n{source}\nend\n")
    sections.append("local modules = {\n")
    sections.extend(f"    {name} = build{name}(),\n" for name in MODULES)
    sections.append("}\n"
        "if not game:IsLoaded() then game.Loaded:Wait() end\n"
        "local players=game:GetService(\"Players\")\n"
        "if not players.LocalPlayer then players:GetPropertyChangedSignal(\"LocalPlayer\"):Wait() end\n"
        "return modules.Runtime.Start(modules,getgenv().PCMovementRebuildConfig or {})\n")
    return "\n".join(sections)

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = bundle()
    if args.check:
        assert OUTPUT.exists() and OUTPUT.read_text() == expected, "Standalone bundle is stale"
        print("PASS: standalone matches every source module")
    else:
        OUTPUT.write_text(expected)
        print(f"Built {OUTPUT.name}: {len(expected.encode())} bytes, {len(MODULES)} modules")
